// ===== v104: VALIDADE FORA DA LISTA (a repositora lança um lote que não veio na lista) =====
var vaProd=null,vaSalvo=null,vaRes=null;
function vaBloco(box){
  var hd=document.createElement('div');hd.className='grp vaHd';hd.innerHTML='<span>➕ VALIDADE FORA DA LISTA</span>';box.appendChild(hd);
  var d=document.createElement('div');d.className='vaBox';box.appendChild(d);
  if(vaSalvo){
    d.innerHTML='<div class="vaProd"><div class="d">'+esc(vaSalvo.desc)+'</div><div class="m">validade '+esc(vaSalvo.val)+' · '+esc(vaSalvo.total)+' un</div></div><div class="vaRes ok">✅ <b>Salvo!</b> Validade lançada.</div><div class="vaBt" style="margin-top:10px"><button class="vaScan">📷 BIPAR OUTRO</button><button class="vaNome">🔎 BUSCAR PELO NOME</button></div>';
    d.querySelector('.vaScan').onclick=function(){vaSalvo=null;vaBipar();};d.querySelector('.vaNome').onclick=function(){vaSalvo=null;vaRes=[];renderVAL();setTimeout(function(){var i=document.querySelector('.vaIn');if(i)i.focus();},50);};
  }else if(vaProd){
    var p=vaProd;
    d.innerHTML='<div class="vaProd"><div class="d">'+esc(p.desc)+'</div><div class="m">SKU '+esc(p.sku)+(p.secao?' · '+esc(p.secao):'')+(p.local?' · 📍 '+esc(p.local):'')+(p.media!==''&&p.media!=null?' · vende ~'+String(p.media).replace('.',',')+' por dia':'')+'</div></div>'+
      '<div class="vaLb">VALIDADE QUE ESTÁ NO PRODUTO *</div><div class="vaDt"><input type="date" class="vaVal"></div>'+
      '<ul class="cv vaF"><li><div class="qq"><label>ÁREA DE VENDA *<input class="ia" type="text" inputmode="decimal"></label><label>ESTOQUE<input class="ie" type="text" inputmode="decimal" placeholder="opcional"></label><div class="tt">TOTAL<b class="it">0</b></div></div>'+
      '<div class="bts"><button class="ok">SALVAR</button><button class="nao">CANCELAR</button></div></li></ul>';
    var ia=d.querySelector('.ia'),ie=d.querySelector('.ie'),tt=d.querySelector('.it'),vv=d.querySelector('.vaVal'),bo=d.querySelector('.ok');
    function soma(){tt.textContent=String(((cvNum(ia.value)||0)+(cvNum(ie.value)||0))).replace('.',',');}
    ia.oninput=soma;ie.oninput=soma;
    d.querySelector('.nao').onclick=function(){vibra();vaProd=null;renderVAL();};
    bo.onclick=function(){
      var m=String(vv.value).match(/^(\d{4})-(\d{2})-(\d{2})$/);if(!m){toast('Escolha a validade que está no produto','err');return;}
      var a=cvNum(ia.value);if(a==null||isNaN(a)||a<0){toast('Informe a quantidade da área de venda','err');return;}
      var e=cvNum(ie.value);if(e!=null&&(isNaN(e)||e<0)){toast('Quantidade do estoque inválida','err');return;}
      if(!(a+(e||0))){toast('Quantidade zerada','err');return;}
      var val=m[3]+'/'+m[2]+'/'+m[1];vibra();bo.textContent='…';bo.disabled=true;
      api({acao:'cvAvulso',quem:quem,token:token,sku:p.sku,validade:val,area:ia.value,estoque:ie.value}).then(function(r){
        if(r&&r.ok){vaSalvo={desc:p.desc,val:val,total:String(a+(e||0)).replace('.',',')};vaProd=null;toast('Salvo!','ok');carregarVAL();renderVAL();}
        else if(r&&r.reauth){toast('Sessão expirada — digite o PIN de novo','err');try{localStorage.removeItem('ci_token');}catch(x){}irPin();}
        else{toast('Não deu: '+(r&&r.erro||''),'err');bo.textContent='SALVAR';bo.disabled=false;}
      }).catch(function(){toast('Sem internet — tente de novo','err');bo.textContent='SALVAR';bo.disabled=false;});
    };
  }else{
    d.innerHTML='<div class="vaBt"><button class="vaScan">📷 BIPAR PRODUTO</button><button class="vaNome">🔎 BUSCAR PELO NOME</button></div>'+(vaRes?'<div class="vaBusca"><input class="vaIn" type="search" placeholder="nome do produto" enterkeyhint="search"><ul class="vaUl"></ul></div>':'');
    d.querySelector('.vaScan').onclick=vaBipar;
    d.querySelector('.vaNome').onclick=function(){vaRes=vaRes?null:[];renderVAL();setTimeout(function(){var i=document.querySelector('.vaIn');if(i)i.focus();},50);};
    if(vaRes){
      var inp=d.querySelector('.vaIn'),ul=d.querySelector('.vaUl');
      vaRes.forEach(function(it){var li=document.createElement('li');li.innerHTML='<span>'+esc(it.desc)+'</span><small>'+esc(it.sku)+'</small>';li.onclick=function(){vibra();vaAbrir({sku:it.sku});};ul.appendChild(li);});
      inp.onkeydown=function(ev){if(ev.key!=='Enter')return;ev.preventDefault();var v=inp.value.trim();if(!v)return;inp.blur();
        if(/^[\d\s.-]+$/.test(v)){vaAbrir({codigo:v.replace(/\D/g,'')});return;}
        ul.innerHTML='<li><span>Procurando…</span></li>';
        api({acao:'buscarNome',texto:v,kg:'todos'}).then(function(r){vaRes=(r&&r.itens)||[];if(!vaRes.length)toast('Nada encontrado com "'+v+'"','err');renderVAL();var i=document.querySelector('.vaIn');if(i)i.value=v;}).catch(function(){toast('Sem conexão','err');});};
    }
  }
  var avs=(valCache&&valCache.avs)||[];
  if(avs.length){
    var h2=document.createElement('div');h2.className='grp ok';h2.innerHTML='<span>LANÇADOS POR MIM — 7 DIAS ('+avs.length+')</span>';box.appendChild(h2);
    var ul2=document.createElement('ul');ul2.className='vaMeus';
    avs.forEach(function(x){var li=document.createElement('li');li.innerHTML='<b>'+esc(x.desc)+'</b><br>validade '+esc(String(x.val).slice(0,5))+' · '+esc(x.qtd)+' un · '+esc(x.em);ul2.appendChild(li);});
    box.appendChild(ul2);
  }
}
function vaBipar(){vibra();escanear('fotoVA');}
function vaAbrir(q){
  toast('Buscando o produto…');
  api({acao:'cvAvInfo',quem:quem,token:token,codigo:q.codigo||'',sku:q.sku||''}).then(function(r){
    if(r&&r.ok){vaProd=r;vaRes=null;vaSalvo=null;renderVAL();setTimeout(function(){var b=document.querySelector('.vaBox');if(b)b.scrollIntoView({block:'start',behavior:'smooth'});},60);}
    else if(r&&r.reauth){irPin();}
    else toast((r&&r.erro)||'Produto não encontrado','err');
  }).catch(function(){toast('Sem conexão — tente de novo','err');});
}
SCAN_CB.fotoVA=function(cod){vibra();vaAbrir({codigo:cod});};
$('fotoVA').addEventListener('change',function(){lerFotoPara(this,SCAN_CB.fotoVA);});
